"""Write the code point ranges whose category is C* or Z* (Python 3.12 unicodedata).

`page_fields.key_allowed` refuses a one-character key in those categories.
"""
import sys, unicodedata
rows, start = [], None
for cp in range(0x110000):
    bad = unicodedata.category(chr(cp))[0] in "CZ"
    if bad and start is None:
        start = cp
    if not bad and start is not None:
        rows.append("%X\t%X" % (start, cp - 1))
        start = None
if start is not None:
    rows.append("%X\t%X" % (start, 0x10FFFF))
with open(sys.argv[1], "w") as fh:
    fh.write("# Python %s unicodedata %s categories C* and Z*; generated by tests/fixtures/capture/gen_keycat.py\n" % (sys.version.split()[0], unicodedata.unidata_version))
    fh.write("\n".join(rows) + "\n")
print(len(rows))
